import React, { useState, useEffect } from 'react';
import axios from 'axios';

const PagosClientesSuperAdmin = () => {
  const [pagos, setPagos] = useState([]);
  const [documentos, setDocumentos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [expandedClientes, setExpandedClientes] = useState({});
  const [expandedDocumentos, setExpandedDocumentos] = useState({});
  const [montoPago, setMontoPago] = useState('');
  const [fechaPago, setFechaPago] = useState(new Date().toISOString().split('T')[0]);
  const [clienteSeleccionado, setClienteSeleccionado] = useState(null);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    const token = localStorage.getItem("auth");
    try {
      const [pagosRes, docsRes] = await Promise.all([
        axios.get('https://sistemacontable-wico.onrender.com/api/listar_cobro/', {
          headers: { Authorization: `Bearer ${token}` }
        }),
        axios.get('https://sistemacontable-wico.onrender.com/api/listar_documentacion/', {
          headers: { Authorization: `Bearer ${token}` }
        })
      ]);
      
      setPagos(pagosRes.data);
      setDocumentos(docsRes.data);
      setLoading(false);
      
      verificarPagosCompletos(pagosRes.data);
    } catch (err) {
      setError(err.message);
      setLoading(false);
    }
  };

  const verificarPagosCompletos = async (pagosData) => {
    const token = localStorage.getItem("auth");
    
    const pagosPorCliente = pagosData.reduce((acc, pago) => {
      if (!acc[pago.cliente.id]) {
        acc[pago.cliente.id] = [];
      }
      acc[pago.cliente.id].push(pago);
      return acc;
    }, {});
    
    for (const clienteId in pagosPorCliente) {
      const tienePendientes = pagosPorCliente[clienteId].some(p => !p.pagado);
      const cliente = pagosPorCliente[clienteId][0].cliente;
      
      if (!tienePendientes && cliente.fondo > 0) {
        try {
          await axios.put(
            `https://sistemacontable-wico.onrender.com/api/limpiar_fondo/${clienteId}/`,
            {},
            { headers: { Authorization: `Bearer ${token}` } }
          );
          
          setPagos(prevPagos => prevPagos.map(pago => {
            if (pago.cliente.id === parseInt(clienteId)) {
              return {
                ...pago,
                cliente: {
                  ...pago.cliente,
                  fondo: 0,
                  fecha_fondo: null
                }
              };
            }
            return pago;
          }));
        } catch (err) {
          console.error(`Error limpiando fondos para cliente ${clienteId}:`, err);
        }
      }
    }
  };

  const aplicarPagoConFondo = async () => {
    if (!clienteSeleccionado || !montoPago || parseFloat(montoPago) <= 0 || !fechaPago) return;
    
    const token = localStorage.getItem("auth");
    try {
      const cliente = pagos.find(p => p.cliente.id === clienteSeleccionado)?.cliente;
      const cobrosPendientes = pagos.filter(
        p => p.cliente.id === clienteSeleccionado && !p.pagado
      );
      
      if (!cliente || cobrosPendientes.length === 0) {
        alert("El cliente no tiene cobros pendientes");
        return;
      }
      
      const fondoActual = cliente.fondo || 0;
      const totalDisponible = parseFloat(montoPago) + fondoActual;
      let saldo = totalDisponible;
      const serviciosAMarcar = [];
      
      const cobrosOrdenados = [...cobrosPendientes].sort((a, b) => 
        new Date(a.fecha_creacion || 0) - new Date(b.fecha_creacion || 0)
      );
      
      for (const cobro of cobrosOrdenados) {
        if (saldo <= 0) break;
        
        const unidades = [...cobro.contenido || [], ...cobro.contenido_open || [], ...cobro.contenido_spr || []]
                        .reduce((sum, item) => sum + item.unidades, cobro.unidades || 0);
        const montoServicio = unidades * 1;
        
        if (saldo >= montoServicio) {
          serviciosAMarcar.push(cobro.id);
          saldo -= montoServicio;
        } else {
          break;
        }
      }
      
      await Promise.all(
        serviciosAMarcar.map(id =>
          axios.put(
            `https://sistemacontable-wico.onrender.com/api/modificar_estado_cobro/${id}/`,
            { pagado: true },
            { headers: { Authorization: `Bearer ${token}` } }
          )
        )
      );
      
      await axios.put(
        `https://sistemacontable-wico.onrender.com/api/actualizar_fondo/${clienteSeleccionado}/`,
        { 
          fondo: saldo > 0 ? saldo : 0,
          fecha_fondo: saldo > 0 ? fechaPago : null
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      
      const nuevosPagos = pagos.map(pago => {
        if (serviciosAMarcar.includes(pago.id)) {
          return { ...pago, pagado: true };
        }
        if (pago.cliente.id === clienteSeleccionado) {
          return {
            ...pago,
            cliente: {
              ...pago.cliente,
              fondo: saldo > 0 ? saldo : 0,
              fecha_fondo: saldo > 0 ? fechaPago : null
            }
          };
        }
        return pago;
      });
      
      setPagos(nuevosPagos);
      setMontoPago('');
      setClienteSeleccionado(null);
      
      const todosPagados = !nuevosPagos.some(
        p => p.cliente.id === clienteSeleccionado && !p.pagado
      );
      
      if (todosPagados && saldo > 0) {
        await axios.put(
          `https://sistemacontable-wico.onrender.com/api/limpiar_fondo/${clienteSeleccionado}/`,
          {},
          { headers: { Authorization: `Bearer ${token}` } }
        );
        
        setPagos(nuevosPagos.map(pago => {
          if (pago.cliente.id === clienteSeleccionado) {
            return {
              ...pago,
              cliente: {
                ...pago.cliente,
                fondo: 0,
                fecha_fondo: null
              }
            };
          }
          return pago;
        }));
      }
      
      alert(`Pago aplicado correctamente. ${
        saldo > 0 ? `Fondo residual: $${saldo.toFixed(2)}` : 'Todos los servicios pagados'
      }`);
      
    } catch (err) {
      console.error("Error al aplicar pago:", err);
      alert("No se pudo aplicar el pago: " + (err.response?.data?.message || err.message));
    }
  };

  const getTipoTarea = (tipo) => {
    switch(tipo) {
      case 1: return 'Notas';
      case 2: return 'Subir Notas';
      case 3: return 'Bill';
      case 4: return 'Open';
      case 5: return 'SPR';
      default: return 'Desconocido';
    }
  };

  const getFechaCreacion = (docId) => {
    const doc = documentos.find(d => d.id === docId);
    return doc ? doc.fecha_creacion : 'Fecha no disponible';
  };

  const getAgenciasNames = (agencias) => {
    if (!agencias || !Array.isArray(agencias)) return 'N/A';
    return agencias.map(a => a.nombre).join(', ') || 'N/A';
  };

  const toggleCliente = (clienteId) => {
    setExpandedClientes(prev => ({
      ...prev,
      [clienteId]: !prev[clienteId]
    }));
  };

  const toggleDocumento = (docId) => {
    setExpandedDocumentos(prev => ({
      ...prev,
      [docId]: !prev[docId]
    }));
  };

  const procesarDatos = () => {
    const clientesMap = new Map();
    
    pagos.forEach(pago => {
      if (!clientesMap.has(pago.cliente.id)) {
        clientesMap.set(pago.cliente.id, {
          id: pago.cliente.id,
          nombre: pago.cliente.nombre,
          agencias: pago.cliente.agencias,
          fondo: pago.cliente.fondo || 0,
          fecha_fondo: pago.cliente.fecha_fondo || null,
          documentos: new Map(),
          totalUnidades: 0,
          totalMonto: 0,
          deuda: 0,
          pagado: 0,
          deudaConFondo: 0
        });
      }
      
      const cliente = clientesMap.get(pago.cliente.id);
      
      if (!cliente.documentos.has(pago.documento.id)) {
        cliente.documentos.set(pago.documento.id, {
          id: pago.documento.id,
          nombre: pago.documento.nombre_documento,
          fecha_creacion: getFechaCreacion(pago.documento.id),
          tareas: [],
          totalUnidades: 0,
          totalMonto: 0,
          deuda: 0,
          pagado: 0
        });
      }
      
      const documento = cliente.documentos.get(pago.documento.id);
      
      const unidades = [...pago.contenido || [], ...pago.contenido_open || [], ...pago.contenido_spr || []]
                      .reduce((sum, item) => sum + item.unidades, pago.unidades || 0);
      const monto = unidades * 1;
      
      const tarea = {
        id: pago.id,
        tipo: pago.tipo_tarea,
        tipo_nombre: getTipoTarea(pago.tipo_tarea),
        mes: pago.mes,
        unidades: unidades,
        monto: monto,
        contenido: [...pago.contenido || [], ...pago.contenido_open || [], ...pago.contenido_spr || []],
        tieneContenido: (pago.contenido?.length > 0) || 
                       (pago.contenido_open?.length > 0) || 
                       (pago.contenido_spr?.length > 0),
        pagado: pago.pagado
      };
      
      documento.tareas.push(tarea);
      documento.totalUnidades += unidades;
      documento.totalMonto += monto;
      
      if (pago.pagado) {
        documento.pagado += monto;
        cliente.pagado += monto;
      } else {
        documento.deuda += monto;
        cliente.deuda += monto;
      }
      
      cliente.totalUnidades += unidades;
      cliente.totalMonto += monto;
    });
    
    clientesMap.forEach(cliente => {
      cliente.deudaConFondo = Math.max(0, cliente.deuda - cliente.fondo);
    });
    
    const clientesArray = Array.from(clientesMap.values()).sort((a, b) => 
      a.nombre.localeCompare(b.nombre)
    );
    
    clientesArray.forEach(cliente => {
      cliente.documentos = Array.from(cliente.documentos.values()).sort((a, b) => 
        a.nombre.localeCompare(b.nombre)
      );
      
      cliente.documentos.forEach(doc => {
        doc.tareas.sort((a, b) => a.tipo - b.tipo);
      });
    });
    
    return clientesArray;
  };

  if (loading) return (
    <div className="d-flex justify-content-center mt-5">
      <div className="spinner-border text-primary" role="status">
        <span className="visually-hidden">Cargando...</span>
      </div>
    </div>
  );

  if (error) return (
    <div className="alert alert-danger mt-3">
      Error al cargar los datos: {error}
    </div>
  );

  const datosProcesados = procesarDatos();
  const totalDeuda = datosProcesados.reduce((sum, c) => sum + c.deuda, 0);
  const totalPagado = datosProcesados.reduce((sum, c) => sum + c.pagado, 0);
  const totalGeneral = datosProcesados.reduce((sum, c) => sum + c.totalMonto, 0);
  const totalDeudaConFondo = datosProcesados.reduce((sum, c) => sum + c.deudaConFondo, 0);
  const totalFondos = datosProcesados.reduce((sum, c) => sum + c.fondo, 0);

  const clientesUnicos = pagos.reduce((acc, pago) => {
    if (!acc.some(c => c.id === pago.cliente.id)) {
      acc.push(pago.cliente);
    }
    return acc;
  }, []).sort((a, b) => a.nombre.localeCompare(b.nombre));

  return (
    <div className="container-fluid mt-3">
      <div className="card mb-3 shadow">
        <div className="card-header bg-primary text-white">
          <h4>Registrar Pago</h4>
        </div>
        <div className="card-body">
          <div className="row g-3">
            <div className="col-md-4">
              <label className="form-label">Cliente</label>
              <select
                className="form-select"
                value={clienteSeleccionado || ''}
                onChange={(e) => setClienteSeleccionado(e.target.value ? parseInt(e.target.value) : null)}
              >
                <option value="">Seleccionar cliente</option>
                {clientesUnicos.map(cliente => (
                  <option key={cliente.id} value={cliente.id}>
                    {cliente.nombre} {cliente.fondo > 0 ? `(Fondo: $${cliente.fondo.toFixed(2)})` : ''}
                  </option>
                ))}
              </select>
            </div>
            <div className="col-md-3">
              <label className="form-label">Monto del pago</label>
              <div className="input-group">
                <span className="input-group-text">$</span>
                <input
                  type="number"
                  className="form-control"
                  value={montoPago}
                  onChange={(e) => setMontoPago(e.target.value)}
                  placeholder="Ingrese el monto"
                  min="0"
                  step="0.01"
                />
              </div>
            </div>
            <div className="col-md-3">
              <label className="form-label">Fecha del pago</label>
              <input
                type="date"
                className="form-control"
                value={fechaPago}
                onChange={(e) => setFechaPago(e.target.value)}
                max={new Date().toISOString().split('T')[0]}
              />
            </div>
            <div className="col-md-2 d-flex align-items-end">
              <button
                className="btn btn-success w-100"
                onClick={aplicarPagoConFondo}
                disabled={!clienteSeleccionado || !montoPago || parseFloat(montoPago) <= 0 || !fechaPago}
              >
                Aplicar Pago
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="card shadow">
        <div className="card-header bg-dark text-white d-flex justify-content-between align-items-center">
          <h3 className="m-0">Pagos de Clientes</h3>
          <div>
            <span className="badge bg-info me-2">Clientes: {datosProcesados.length}</span>
            <span className="badge bg-danger me-2">
              Deuda: ${totalDeudaConFondo.toFixed(2)} (${totalDeuda.toFixed(2)})
            </span>
            <span className="badge bg-success me-2">Pagado: ${totalPagado.toFixed(2)}</span>
            <span className="badge bg-warning">Fondos: ${totalFondos.toFixed(2)}</span>
          </div>
        </div>
        <div className="card-body p-0">
          <div className="table-responsive">
            <table className="table table-bordered table-hover mb-0">
              <thead className="table-dark sticky-top">
                <tr>
                  <th>#</th>
                  <th>Cliente</th>
                  <th>Agencia(s)</th>
                  <th>Documento</th>
                  <th>Fecha</th>
                  <th>Tipo Tarea</th>
                  <th>Unidades</th>
                  <th>Monto</th>
                  <th>Estado</th>
                  <th className="text-danger">Deuda</th>
                  <th className="text-success">Pagado</th>
                </tr>
              </thead>
              <tbody>
                {datosProcesados.map((cliente, idxCliente) => (
                  <React.Fragment key={`cliente-${cliente.id}`}>
                    <tr 
                      className="table-primary fw-bold" 
                      onClick={() => toggleCliente(cliente.id)}
                      style={{ cursor: 'pointer' }}
                    >
                      <td className="text-center">{idxCliente + 1}</td>
                      <td>{cliente.nombre}</td>
                      <td>{getAgenciasNames(cliente.agencias)}</td>
                      <td colSpan="3" className="text-end">Total cliente:</td>
                      <td className="text-end">{cliente.totalUnidades}</td>
                      <td className="text-end">${cliente.totalMonto.toFixed(2)}</td>
                      <td></td>
                      <td className="text-end text-danger fw-bold">
                        ${cliente.deudaConFondo.toFixed(2)} (${cliente.deuda.toFixed(2)})
                        {cliente.fondo > 0 && <div className="small">Fondo: ${cliente.fondo.toFixed(2)}</div>}
                      </td>
                      <td className="text-end text-success fw-bold">${cliente.pagado.toFixed(2)}</td>
                    </tr>
                    
                    {expandedClientes[cliente.id] && cliente.documentos.map((documento, idxDoc) => (
                      <React.Fragment key={`doc-${documento.id}`}>
                        <tr 
                          className="table-info" 
                          onClick={() => toggleDocumento(documento.id)}
                          style={{ cursor: 'pointer' }}
                        >
                          <td className="text-end">{idxCliente + 1}.{idxDoc + 1}</td>
                          <td colSpan="3">{documento.nombre}</td>
                          <td>{documento.fecha_creacion}</td>
                          <td className="text-end">Total documento:</td>
                          <td className="text-end">{documento.totalUnidades}</td>
                          <td className="text-end">${documento.totalMonto.toFixed(2)}</td>
                          <td></td>
                          <td className="text-end text-danger">${documento.deuda.toFixed(2)}</td>
                          <td className="text-end text-success">${documento.pagado.toFixed(2)}</td>
                        </tr>
                        
                        {expandedDocumentos[documento.id] && documento.tareas.map((tarea, idxTarea) => (
                          <React.Fragment key={`tarea-${tarea.id}`}>
                            <tr className={tarea.pagado ? 'table-light' : 'table-warning'}>
                              <td colSpan="5"></td>
                              <td>
                                {tarea.tipo_nombre} - {tarea.mes}
                              </td>
                              <td className="text-end">{tarea.unidades}</td>
                              <td className="text-end">${tarea.monto.toFixed(2)}</td>
                              <td className="text-center">
                                <span className={`badge ${tarea.pagado ? 'bg-success' : 'bg-warning'}`}>
                                  {tarea.pagado ? 'Pagado' : 'Pendiente'}
                                </span>
                              </td>
                              <td className="text-end">
                                {!tarea.pagado && `$${tarea.monto.toFixed(2)}`}
                              </td>
                              <td className="text-end">
                                {tarea.pagado && `$${tarea.monto.toFixed(2)}`}
                              </td>
                            </tr>
                            
                            {tarea.tieneContenido && tarea.contenido.map((registro, idxReg) => (
                              <tr key={`reg-${registro.id}`} className="table-white">
                                <td colSpan="5"></td>
                                <td className="ps-4 small">
                                  <i className="bi bi-person-fill me-1"></i>
                                  {registro.nombre_completo} ({tarea.tipo_nombre})
                                </td>
                                <td className="text-end small">{registro.unidades}</td>
                                <td className="text-end small">${registro.unidades.toFixed(2)}</td>
                                <td colSpan="3"></td>
                              </tr>
                            ))}
                          </React.Fragment>
                        ))}
                      </React.Fragment>
                    ))}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        </div>
        <div className="card-footer bg-light">
          <div className="row align-items-center">
            <div className="col-md-4">
              <span className="badge bg-primary me-2">Cliente</span>
              <span className="badge bg-info me-2">Documento</span>
              <span className="badge bg-light text-dark border">Tarea</span>
            </div>
            <div className="col-md-8 text-md-end">
              <strong className="me-3">Total general: ${totalGeneral.toFixed(2)}</strong>
              <strong className="text-danger me-3">Deuda neta: ${totalDeudaConFondo.toFixed(2)}</strong>
              <strong className="text-success">Pagado: ${totalPagado.toFixed(2)}</strong>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PagosClientesSuperAdmin;