import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ComparativaTotalCobrar = () => {
  const [cobrosEstimados, setCobrosEstimados] = useState([]);
  const [cobrosReales, setCobrosReales] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [expandedClientes, setExpandedClientes] = useState({});
  const [expandedDocumentos, setExpandedDocumentos] = useState({});

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    const token = localStorage.getItem("auth");
    try {
      const [estimadosRes, realesRes] = await Promise.all([
        axios.get('https://sistemacontable-wico.onrender.com/api/listar_cobros_estimados/', {
          headers: { Authorization: `Bearer ${token}` }
        }),
        axios.get('https://sistemacontable-wico.onrender.com/api/listar_cobro/', {
          headers: { Authorization: `Bearer ${token}` }
        })
      ]);
      
      setCobrosEstimados(estimadosRes.data);
      setCobrosReales(realesRes.data);
      setLoading(false);
    } catch (err) {
      setError(err.message);
      setLoading(false);
    }
  };

  const getTipoTarea = (tipo) => {
    switch(tipo) {
      case 1: return 'Notas';
      case 2: return 'Subir Notas';
      case 3: return 'Bill';
      case 4: return 'Open';
      case 5: return 'SPR';
      default: return 'Desconocido';
    }
  };

  const getTotalEstimado = (documentoId) => {
    const estimado = cobrosEstimados.find(e => e.documento.id === documentoId);
    if (!estimado) return 0;
    
    return (estimado.bill || 0) + (estimado.notas || 0) + (estimado.subir_notas || 0);
  };

  const toggleCliente = (clienteId) => {
    setExpandedClientes(prev => ({
      ...prev,
      [clienteId]: !prev[clienteId]
    }));
  };

  const toggleDocumento = (docId) => {
    setExpandedDocumentos(prev => ({
      ...prev,
      [docId]: !prev[docId]
    }));
  };

  const procesarDatos = () => {
    const clientesMap = new Map();
    
    cobrosReales.forEach(cobro => {
      if (!clientesMap.has(cobro.cliente.id)) {
        clientesMap.set(cobro.cliente.id, {
          id: cobro.cliente.id,
          nombre: cobro.cliente.nombre,
          agencias: cobro.cliente.agencias,
          documentos: new Map(),
          totalUnidades: 0,
          totalMonto: 0,
          totalEstimado: 0
        });
      }
      
      const cliente = clientesMap.get(cobro.cliente.id);
      
      if (!cliente.documentos.has(cobro.documento.id)) {
        cliente.documentos.set(cobro.documento.id, {
          id: cobro.documento.id,
          nombre: cobro.documento.nombre_documento,
          tareas: [],
          totalUnidades: 0,
          totalMonto: 0,
          totalEstimado: getTotalEstimado(cobro.documento.id)
        });
      }
      
      const documento = cliente.documentos.get(cobro.documento.id);
      
      const unidades = [...cobro.contenido || [], ...cobro.contenido_open || [], ...cobro.contenido_spr || []]
                      .reduce((sum, item) => sum + item.unidades, cobro.unidades || 0);
      const monto = unidades * 1;
      
      const tarea = {
        id: cobro.id,
        tipo: cobro.tipo_tarea,
        tipo_nombre: getTipoTarea(cobro.tipo_tarea),
        mes: cobro.mes,
        unidades: unidades,
        monto: monto,
        contenido: [...cobro.contenido || [], ...cobro.contenido_open || [], ...cobro.contenido_spr || []],
        tieneContenido: (cobro.contenido?.length > 0) || 
                       (cobro.contenido_open?.length > 0) || 
                       (cobro.contenido_spr?.length > 0)
      };
      
      documento.tareas.push(tarea);
      documento.totalUnidades += unidades;
      documento.totalMonto += monto;
      
      cliente.totalUnidades += unidades;
      cliente.totalMonto += monto;
      cliente.totalEstimado += documento.totalEstimado;
    });
    
    const clientesArray = Array.from(clientesMap.values()).sort((a, b) => 
      a.nombre.localeCompare(b.nombre)
    );
    
    clientesArray.forEach(cliente => {
      cliente.documentos = Array.from(cliente.documentos.values()).sort((a, b) => 
        a.nombre.localeCompare(b.nombre)
      );
      
      cliente.documentos.forEach(doc => {
        doc.tareas.sort((a, b) => a.tipo - b.tipo);
      });
    });
    
    return clientesArray;
  };

  if (loading) return (
    <div className="d-flex justify-content-center mt-5">
      <div className="spinner-border text-primary" role="status">
        <span className="visually-hidden">Cargando...</span>
      </div>
    </div>
  );

  if (error) return (
    <div className="alert alert-danger mt-3">
      Error al cargar los datos: {error}
    </div>
  );

  const datosProcesados = procesarDatos();
  const totalMonto = datosProcesados.reduce((sum, c) => sum + c.totalMonto, 0);
  const totalEstimado = datosProcesados.reduce((sum, c) => sum + c.totalEstimado, 0);

  return (
    <div className="container-fluid mt-3">
      <div className="card shadow">
        <div className="card-header bg-dark text-white d-flex justify-content-between align-items-center">
          <h3 className="m-0">Comparativa Total a Cobrar</h3>
          <div>
            <span className="badge bg-info me-2">Clientes: {datosProcesados.length}</span>
            <span className="badge bg-primary me-2">Cobros: ${totalMonto.toFixed(2)}</span>
            <span className="badge bg-warning">Estimado: ${totalEstimado.toFixed(2)}</span>
          </div>
        </div>
        <div className="card-body p-0">
          <div className="table-responsive">
            <table className="table table-bordered table-hover mb-0">
              <thead className="table-dark sticky-top">
                <tr>
                  <th>#</th>
                  <th>Cliente</th>
                  <th>Agencia(s)</th>
                  <th>Documento</th>
                  <th>Tipo Tarea</th>
                  <th>Unidades</th>
                  <th>Cobros Insertados</th>
                  <th>Cobros Estimados</th>
                  <th>Acciones</th>
                </tr>
              </thead>
              <tbody>
                {datosProcesados.map((cliente, idxCliente) => (
                  <React.Fragment key={`cliente-${cliente.id}`}>
                    <tr 
                      className="table-primary fw-bold" 
                      onClick={() => toggleCliente(cliente.id)}
                      style={{ cursor: 'pointer' }}
                    >
                      <td className="text-center">{idxCliente + 1}</td>
                      <td>{cliente.nombre}</td>
                      <td>{cliente.agencias?.map(a => a.nombre).join(', ') || 'N/A'}</td>
                      <td colSpan="2" className="text-end">Total cliente:</td>
                      <td className="text-end">{cliente.totalUnidades}</td>
                      <td className="text-end">${cliente.totalMonto.toFixed(2)}</td>
                      <td className="text-end">${cliente.totalEstimado.toFixed(2)}</td>
                      <td></td>
                    </tr>
                    
                    {expandedClientes[cliente.id] && cliente.documentos.map((documento, idxDoc) => (
                      <React.Fragment key={`doc-${documento.id}`}>
                        <tr 
                          className="table-info" 
                          onClick={() => toggleDocumento(documento.id)}
                          style={{ cursor: 'pointer' }}
                        >
                          <td className="text-end">{idxCliente + 1}.{idxDoc + 1}</td>
                          <td colSpan="2"></td>
                          <td>{documento.nombre}</td>
                          <td className="text-end">Total documento:</td>
                          <td className="text-end">{documento.totalUnidades}</td>
                          <td className="text-end">${documento.totalMonto.toFixed(2)}</td>
                          <td className="text-end">${documento.totalEstimado.toFixed(2)}</td>
                          <td></td>
                        </tr>
                        
                        {expandedDocumentos[documento.id] && documento.tareas.map((tarea, idxTarea) => (
                          <tr key={`tarea-${tarea.id}`} className="table-light">
                            <td colSpan="3"></td>
                            <td></td>
                            <td>
                              {tarea.tipo_nombre} - {tarea.mes}
                            </td>
                            <td className="text-end">{tarea.unidades}</td>
                            <td className="text-end">${tarea.monto.toFixed(2)}</td>
                            <td className="text-end">
                              {tarea.tipo === 1 && cobrosEstimados.find(e => e.documento.id === documento.id)?.notas?.toFixed(2)}
                              {tarea.tipo === 2 && cobrosEstimados.find(e => e.documento.id === documento.id)?.subir_notas?.toFixed(2)}
                              {tarea.tipo === 3 && cobrosEstimados.find(e => e.documento.id === documento.id)?.bill?.toFixed(2)}
                            </td>
                            <td className="text-center">
                              <button className="btn btn-sm btn-success me-2">
                                <i className="bi bi-plus"></i>
                              </button>
                              <button className="btn btn-sm btn-danger">
                                <i className="bi bi-dash"></i>
                              </button>
                            </td>
                          </tr>
                        ))}
                      </React.Fragment>
                    ))}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        </div>
        <div className="card-footer bg-light">
          <div className="row align-items-center">
            <div className="col-md-4">
              <span className="badge bg-primary me-2">Cliente</span>
              <span className="badge bg-info me-2">Documento</span>
              <span className="badge bg-light text-dark border">Tarea</span>
            </div>
            <div className="col-md-8 text-md-end">
              <strong className="me-3">Total cobros: ${totalMonto.toFixed(2)}</strong>
              <strong className="text-warning">Total estimado: ${totalEstimado.toFixed(2)}</strong>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ComparativaTotalCobrar;